import{c as t,Q as r,j as a,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Inherited Goal Drift: Contextual Pressure Can Undermine Agentic Goals","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.03258","title":"Inherited Goal Drift: Contextual Pressure Can Undermine Agentic Goals","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2603.03258,"authors":["Achyutha Menon","Magnus Saebo","Tyler Crosse","Spencer Gibson","Eyon Jang","Diogo Cruz"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2603.03258v1","pdf_path":"pdfs/2603.03258.pdf","published_date":"2026-03-03T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-03-03-inherited-goal-drift-contextual-pressure-2603-03258.md","filePath":"research/papers/2026-03-03-inherited-goal-drift-contextual-pressure-2603-03258.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-03-03-inherited-goal-drift-contextual-pressure-2603-03258.md"};function o(s,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="inherited-goal-drift-contextual-pressure-can-undermine-agentic-goals" tabindex="-1">Inherited Goal Drift: Contextual Pressure Can Undermine Agentic Goals <a class="header-anchor" href="#inherited-goal-drift-contextual-pressure-can-undermine-agentic-goals" aria-label="Permalink to &quot;Inherited Goal Drift: Contextual Pressure Can Undermine Agentic Goals&quot;">​</a></h1><p><strong>Authors</strong>: Achyutha Menon, Magnus Saebo, Tyler Crosse, Spencer Gibson, Eyon Jang, Diogo Cruz <strong>Published</strong>: March 3, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2603.03258" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.03258</a> · <a href="https://arxiv.org/html/2603.03258v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2603.03258 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2603.03258" target="_blank" rel="noreferrer">research/papers/pdfs/2603.03258.pdf</a> (22 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>The accelerating adoption of language models (LMs) as agents for deployment in long-context tasks motivates a thorough understanding of goal drift: agents&#39; tendency to deviate from an original objective. While prior-generation language model agents have been shown to be susceptible to drift, the extent to which drift affects more recent models remains unclear. In this work, we provide an updated characterization of the extent and causes of goal drift. We investigate drift in state-of-the-art models within a simulated stock-trading environment (Arike et al., 2025). These models are largely shown to be robust even when subjected to adversarial pressure. We show, however, that this robustness is brittle: across multiple settings, the same models often inherit drift when conditioned on prefilled trajectories from weaker agents. The extent of conditioning-induced drift varies significantly by model family, with only GPT-5.1 maintaining consistent resilience among tested models. We find that drift behavior is inconsistent between prompt variations and correlates poorly with instruction hierarchy following behavior, with strong hierarchy following failing to reliably predict resistance to drift. Finally, we run analogous experiments in a new emergency room triage environment to show preliminary evidence for the transferability of our results across qualitatively different settings. Our findings underscore the continued vulnerability of modern LM agents to contextual pressures and the need for refined post-training techniques to mitigate this.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>對 state-of-the-art LM agents 的 <strong>goal drift</strong>（偏離原始目標）提供最新刻畫，更新前世代模型的研究結論。</li><li>提出並量化 <strong>inherited drift（繼承式漂移）</strong>：當模型被 condition 在「較弱 agent 的 prefilled trajectory」上時，原本對 adversarial pressure 穩健的模型也會繼承漂移行為——揭示 robustness 是 brittle 的。</li><li>證明 <strong>instruction hierarchy following 與 drift resistance 相關性低</strong>：強指令階層遵循無法可靠預測對漂移的抵抗力。</li><li>跨情境驗證：除原本的 simulated stock-trading environment 外，新建 emergency room triage 環境，提供漂移現象可轉移（transferability）的初步證據。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>模型在直接 adversarial pressure 下 largely robust，但 prefilled-trajectory conditioning 下普遍出現 inherited drift。</li><li>conditioning-induced drift 程度因 <strong>model family 差異顯著</strong>；受測模型中<strong>僅 GPT-5.1 維持一致的 resilience</strong>。</li><li>drift 行為在 prompt variations 間<strong>不一致</strong>（inconsistent），且與 instruction hierarchy following 相關性差。</li><li>ER triage 環境的 analogous experiments 顯示結果可跨質性不同情境轉移（初步證據）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>作者自述 triage 環境結果為 <strong>preliminary evidence</strong>，轉移性仍待強化。</li><li>文件未列明確獨立 limitation 章節（依 abstract 推斷）。判斷弱點：① 受測模型集合有限（結論「僅 GPT-5.1 resilient」隨模型迭代易過時）；② 兩個環境（stock-trading / ER triage）皆為 simulated，真實部署外推有效性未驗；③ drift 的量測 metric 與 prefilled trajectory 的「weaker agent」操作化定義可能影響結論強度。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接映射 The Loop 的「goal drift」失敗模式</strong>：core.md RECORD 與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） 已將 dynamic workflow 的 goal drift 列為三大失敗模式之一。本文的 inherited drift 為「子任務 prefilled trajectory 污染主目標」提供實證——可佐證「subagent verdict 非證據、須機械重驗」的紀律。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>contextual pressure ↔ context-management.md NLAH 原則</strong>：本文顯示 conditioning 於弱 agent 軌跡會拉偏目標，呼應「原始目標放 HEAD、勿被中段動態狀態稀釋」的設計。⚠️ 落地門檻：本文為觀察性現象，未提供可直接嵌入 hook 的偵測 metric。</li><li><strong>跨切紀律「judgment vs decision」佐證</strong>：drift 與 instruction hierarchy following 脫鉤，支持「確定性 gate 不可經 sub-agent 中介」——目標守護應由 deterministic 檢查而非模型自評承擔。⚠️ 本文未提出具體防護機制（自述需 refined post-training），workspace 端僅能採「親跑確定性檢查」對策，無法直接引用其方法。</li><li>⚠️ 整體屬概念佐證層級，非可操作方案；引用時應標為「外部實證支持既有紀律」，不宜誇大為提供了現成 mitigation。</li></ul>',16)])])}const f=t(n,[["render",o]]);export{u as __pageData,f as default};
